import functools

def solve_game(n, turn):
    # turn: 0 for Alice (maximize), 1 for Bob (minimize)
    # board: tuple of boolean, True if occupied
    state = (False,) * n

    @functools.lru_cache(None)
    def play(board, turn):
        # Find all possible moves
        moves = []
        for i in range(n - 1):
            if not board[i] and not board[i+1]:
                moves.append(i)

        if not moves:
            # Game ends, count uncovered squares
            return sum(1 for x in board if not x)

        if turn == 0: # Alice's turn
            best_val = -float('inf')
            for move in moves:
                new_board = list(board)
                new_board[move] = True
                new_board[move+1] = True
                val = play(tuple(new_board), 1)
                best_val = max(best_val, val)
            return best_val
        else: # Bob's turn
            best_val = float('inf')
            for move in moves:
                new_board = list(board)
                new_board[move] = True
                new_board[move+1] = True
                val = play(tuple(new_board), 0)
                best_val = min(best_val, val)
            return best_val

    return play(state, turn)

for n in range(1, 16):
    print(f"n={n}: {solve_game(n, 0)}")

