import functools

@functools.lru_cache(None)
def play(segments, turn):
    # segments: sorted tuple of segment lengths
    # turn: 0 for Alice (maximize), 1 for Bob (minimize)

    # Find all possible moves
    # A move consists of choosing a segment of length L and a position i
    # The segment is split into length i and length L-i-2.

    possible_moves = []
    for seg_idx, L in enumerate(segments):
        for i in range(L - 1):
            # Move at i, i+1
            # New segments: (i) and (L-i-2)
            new_segments = list(segments)
            new_segments.pop(seg_idx)
            if i > 0:
                new_segments.append(i)
            if L - i - 2 > 0:
                new_segments.append(L - i - 2)
            possible_moves.append(tuple(sorted(new_segments, reverse=True)))

    if not possible_moves:
        # Game ends. The number of uncovered squares is the sum of 
        # uncovered squares in each segment.
        # However, the game only ends when no segment has length >= 2.
        # So each remaining segment must have length 1.
        return sum(segments)

    if turn == 0: # Alice
        return max(play(move, 1) for move in possible_moves)
    else: # Bob
        return min(play(move, 0) for move in possible_moves)

